INSERT INTO feature VALUES('cam-wire','storage','A value''s chunks fetched by content between processes','value-plane','implemented','notable',NULL,'An endpoint serves the chunks its host commits under `gandr/chunks/0`, and a fetch asks a peer once for the closure of a value it lacks, naming the values it holds: the holder answers with the wanted closure less the held closures, and the asker verifies every chunk against its digest before it keeps any. A second fetch of an edited value, naming the first as held, carries the chunks the edit added and their bytes alone, inside the locality bound; a chunk that does not verify refuses the answer with nothing kept.','runtime-net storage-values','crates/runtime-net/tests/chunks.rs corpus/model/worlds/two-processes.gandr',NULL,NULL);
